def ddp_mean_weights(counts):
    if not counts or any(not isinstance(n, int) or n < 0 for n in counts):
        raise ValueError('有效计数不合法')
    total = sum(counts)
    if total == 0:
        raise ValueError('全局没有有效元素')
    world_size = len(counts)
    return [world_size * n / total for n in counts]

